    copyLogbookReportMarkdown() {
        const g = window.Game;
        const pInfo = g.propertyInfo || {};
        const pName = pInfo.name || "1910 Whispering Pines Manor";
        const curDay = Number(g.currentDay || 1);
        const startDate = g.getProjectStartDate ? g.getProjectStartDate() : '2026-10-18';
        const curCentralTime = window.Game && window.Game.formatCentralTimestamp 
            ? window.Game.formatCentralTimestamp(Date.now(), true) 
            : new Date().toLocaleString('en-US', { timeZone: 'America/Chicago' });
        const rawLogs = g.activityLog || [];

        let md = `# ${pName} — Log & Accomplishments Dossier\n\n`;
        md += `**Project Timeline:** Started: ${startDate} | Current Central Time: ${curCentralTime}\n`;
        md += `**Total Records:** ${rawLogs.length}\n\n`;
        md += `## Chronological Log Book Entries\n\n`;

        const grouped = new Map();
        rawLogs.forEach(l => {
            const d = Number(l.day || 1);
            if (!grouped.has(d)) grouped.set(d, []);
            grouped.get(d).push(l);
        });
        const sortedDays = Array.from(grouped.keys()).sort((a, b) => b - a);

        sortedDays.forEach(day => {
            const dayItems = grouped.get(day);
            const groupDate = (dayItems[0] && dayItems[0].timestamp)
                ? new Date(dayItems[0].timestamp).toLocaleDateString('en-US', { timeZone: 'America/Chicago', month: '2-digit', day: '2-digit', year: 'numeric' })
                : `Session ${day}`;
            md += `### ${groupDate} (Central Time)\n`;
            dayItems.forEach(item => {
                const tag = item.isAccomplishment ? '[Accomplishment]' : (item.type === 'user_note' ? '[Note]' : '[Log]');
                const timeStampStr = item.timestamp
                    ? new Date(item.timestamp).toLocaleString('en-US', { timeZone: 'America/Chicago', month: '2-digit', day: '2-digit', year: 'numeric', hour: 'numeric', minute: '2-digit', second: '2-digit', hour12: true, timeZoneName: 'short' })
                    : (item.time || groupDate);
                md += `- **${timeStampStr}** ${tag}: ${item.message}\n`;
            });
            md += `\n`;
        });

        if (navigator.clipboard) {
            navigator.clipboard.writeText(md).then(() => {
                if (this.showToast) this.showToast('📋 Full Report copied as Markdown to clipboard!');
            });
        }
    }

