    doTask(taskId, isDIY, lumberType = null) {
        const g = window.Game;
        const task = g.getTask(taskId);
        if (task && g.stopWorkOrders && g.stopWorkOrders[task.room]) {
            if (window.Sound) window.Sound.playError();
            this.showHazardIncidentModal({
                type: 'shutdown',
                title: '🛑 MUNICIPAL STOP-WORK ORDER ACTIVE',
                room: task.room,
                hazardPct: g.calculateRoomHazard(task.room).hazardPct,
                desc: `City Inspector Henderson has halted all work in ${GAME_DATA.ROOMS[task.room]?.name || task.room}! You must clear safety violations or pay the $150 re-inspection fee before construction can resume.`
            });
            return;
        }

        if (isDIY) {
            if (!g.canDoDIY(taskId)) {
                if (window.Sound) window.Sound.playError();
                return;
            }
            this.activeDiyLumberType = lumberType;
            this.startRandomDiyMinigame(taskId);
        } else {
            if (!g.canHireSub(taskId)) {
                if (window.Sound) window.Sound.playError();
                return;
            }
            this.startRandomSubMinigame(taskId);
        }
    }

    liftStopWorkOrder(roomKey, payFee = true) {
        const success = window.Game.liftStopWorkOrder(roomKey, payFee);
        if (success) {
            this.closeHazardModal();
            this.renderRenovationsTab();
            this.renderBlueprintTab();
            this.updateHUD();
        }
    }

    buyLumber(type = 'modern', count = 5) {
        const success = window.Game.buyLumber(type, count);
        if (success) {
            this.renderRenovationsTab();
            this.updateHUD();
        }
    }

    millSalvageLogs(count = 1) {
        const success = window.Game.millSalvageLogs(count);
        if (success) {
            this.renderRenovationsTab();
            this.updateHUD();
        }
    }

    showHazardIncidentModal(incident) {
        const modal = document.getElementById('hazard-modal-overlay');
        const title = document.getElementById('hazard-modal-title');
        const body = document.getElementById('hazard-modal-body');
        if (!modal || !body) return;

        let icon = '🩹';
        let badgeColor = '#ef4444';
        if (incident.type === 'collapse') {
            icon = '💥';
            badgeColor = '#f59e0b';
        } else if (incident.type === 'shutdown') {
            icon = '🛑';
            badgeColor = '#ef4444';
        }

        if (title) title.innerHTML = `${icon} ${incident.title || 'Safety Hazard Incident!'}`;

        body.innerHTML = `
            <div class="hazard-incident-card">
                <div class="hazard-incident-banner" style="border-left:4px solid ${badgeColor};">
                    <span class="incident-icon">${icon}</span>
                    <div>
                        <div class="incident-room-tag">Room: <strong>${GAME_DATA.ROOMS[incident.room]?.name || incident.room}</strong> (${incident.hazardPct || 60}% Danger)</div>
                        <p class="incident-desc">${incident.desc}</p>
                    </div>
                </div>

                <div class="incident-impact-stats">
                    ${incident.staminaLost ? `<div class="incident-stat danger"><span>⚡ Stamina Lost:</span> <strong>-${incident.staminaLost} Stamina</strong></div>` : ''}
                    ${incident.cashLost ? `<div class="incident-stat danger"><span>💸 Outlay Cost:</span> <strong>-$${incident.cashLost}</strong></div>` : ''}
                    ${incident.clutterGained ? `<div class="incident-stat warn"><span>📦 Site Clutter:</span> <strong>+${incident.clutterGained}% Debris</strong></div>` : ''}
                    ${incident.type === 'shutdown' ? `<div class="incident-stat shutdown"><span>🛑 Legal Status:</span> <strong>STOP-WORK ORDER ACTIVE</strong></div>` : ''}
                </div>

                <div class="incident-remedy-note">
                    <strong>🛡️ How to prevent this:</strong> Address structural foundation sagging in the Basement, seal leaky roofs before interior finish work, replace lead pipes, and organize tools to keep site clutter down!
                </div>

                <div class="incident-action-row">
                    ${incident.type === 'shutdown' ? `
                        <button class="btn-lift-fee" onclick="UI.liftStopWorkOrder('${incident.room}', true)">
                            🏛️ Pay $150 Expedited Re-inspection Fee
                        </button>
                    ` : ''}
                    <button class="btn-incident-ok" onclick="UI.closeHazardModal()">
                        ✓ Acknowledge &amp; Continue
                    </button>
                </div>
            </div>
        `;

        modal.style.display = 'flex';
        if (window.Sound) {
            if (incident.type === 'shutdown' || incident.type === 'injury') window.Sound.playError();
            else window.Sound.playHammer();
        }
    }

    closeHazardModal() {
        const modal = document.getElementById('hazard-modal-overlay');
        if (modal) modal.style.display = 'none';
    }

