    closeToolEditorModal() {
        const modal = document.getElementById('tool-editor-modal-overlay');
        if (modal) modal.style.display = 'none';
    }

    saveToolEditor() {
        const nameInput = document.getElementById('tool-edit-name');
        const iconInput = document.getElementById('tool-edit-icon');
        const costInput = document.getElementById('tool-edit-cost');
        const descInput = document.getElementById('tool-edit-desc');
        const ownedInput = document.getElementById('tool-edit-owned');
        if (!nameInput || !nameInput.value.trim()) {
            alert("Please enter a tool name.");
            return;
        }

        window.Game.addCustomTool({
            name: nameInput.value.trim(),
            icon: iconInput ? iconInput.value : '🔧',
            cost: Number(costInput ? costInput.value : 0) || 0,
            desc: descInput ? descInput.value.trim() : '',
            isOwned: ownedInput ? ownedInput.checked : true
        });

        this.closeToolEditorModal();
        this.renderHardwareTab();
        this.updateHUD();
        if (window.Sound) window.Sound.playHammer();
    }

    deleteTool(toolId) {
        const tool = window.Game.getTool(toolId);
        const name = tool ? tool.name : 'this tool';
        if (confirm(`Are you sure you want to delete ${name} from your tool shed?`)) {
            window.Game.deleteTool(toolId);
            this.renderHardwareTab();
            this.updateHUD();
            if (window.Sound) window.Sound.playClick();
        }
    }

