    saveCustomSectionFromModal() {
        const g = window.Game;
        const id = document.getElementById('cs-edit-id')?.value.trim() || ('chs_' + Date.now());
        const title = document.getElementById('cs-edit-title')?.value.trim();
        if (!title) {
            alert('Please provide a section title.');
            return;
        }
        const existing = (g.customHistorySections || []).find(s => s.id === id);
        const section = {
            id,
            icon: document.getElementById('cs-edit-icon')?.value.trim() || '🧱',
            badge: document.getElementById('cs-edit-badge')?.value.trim() || 'CUSTOM SECTION',
            title,
            subtitle: document.getElementById('cs-edit-sub')?.value.trim() || '',
            date: document.getElementById('cs-edit-date')?.value.trim() || 'Survey Day 2',
            color: document.getElementById('cs-edit-color')?.value || '#38bdf8',
            blocks: existing?.blocks || []
        };
        g.saveCustomHistorySection(section);
        this.closeCustomSectionModal();
        this.renderStartingPointTab();
        this.showToast(`✅ Saved section: "${title}"!`);
        if (typeof this.masterSaveAll === 'function') {
            this.masterSaveAll().catch(e => console.warn(e));
        }
    }

