    getHistoryTargetDisplayName(targetPostId) {
        if (!targetPostId) return 'Section';
        if (targetPostId === 'history-section-blueprints') return 'Architectural Blueprints';
        if (targetPostId === 'history-section-slider') return 'Before/Now Split Slider';
        if (targetPostId === 'history-section-leveling') return 'Foundation Leveling Gauge';
        if (targetPostId === 'history-section-salvage') return 'Salvage Timber Reserve';
        if (targetPostId === 'history-section-daily') return 'Daily Maintenance Operations';
        const g = window.Game;
        if (g) {
            const p = (g.startingPointPosts || []).find(item => item.id === targetPostId);
            if (p) return p.title || 'Before Post';
            const n = (g.startingPointNarratives || []).find(item => item.id === targetPostId);
            if (n) return n.header || 'Field Report';
        }
        return 'Post / Section';
    }

    jumpToHistoryTarget(targetPostId) {
        if (!targetPostId) return;
        let el = document.getElementById(targetPostId);
        if (!el) el = document.getElementById('history-post-' + targetPostId);
        if (!el) el = document.getElementById('history-narrative-' + targetPostId);
        if (el) {
            el.scrollIntoView({ behavior: 'smooth', block: 'start' });
            el.style.transition = 'box-shadow 0.3s ease, border-color 0.3s ease';
            const origBorder = el.style.borderColor;
            const origShadow = el.style.boxShadow;
            el.style.borderColor = '#38bdf8';
            el.style.boxShadow = '0 0 24px rgba(56, 189, 248, 0.7)';
            setTimeout(() => {
                el.style.borderColor = origBorder;
                el.style.boxShadow = origShadow;
            }, 1800);
            if (window.Sound) window.Sound.playClick();
        } else {
            console.warn('Target element not found for jump:', targetPostId);
        }
    }

