    publishQuickBeforePost() {
        const title = document.getElementById('quick-post-title')?.value?.trim();
        if (!title) {
            alert('Please enter a title for the Before Post.');
            return;
        }
        const subtitle = document.getElementById('quick-post-subtitle')?.value?.trim() || '';
        const badge = document.getElementById('quick-post-badge')?.value?.trim() || 'STRUCTURAL CRITICAL';
        const date = document.getElementById('quick-post-date')?.value?.trim() || 'Survey Day 1';
        const paragraph = document.getElementById('quick-post-body')?.value?.trim() || '';
        const notes = document.getElementById('quick-post-notes')?.value?.trim() || '';
        const footnoteText = document.getElementById('quick-post-footnote')?.value?.trim() || '';
        const photoUrl = document.getElementById('quick-post-photo-url')?.value?.trim() || 'steampunk109.jpg';
        const photoCaption = document.getElementById('quick-post-photo-caption')?.value?.trim() || title;

        const g = window.Game;
        if (!Array.isArray(g.startingPointPosts)) g.startingPointPosts = [];

        const newPost = {
            id: 'spp_' + Date.now(),
            title,
            subtitle,
            badge,
            date,
            paragraph,
            notes,
            footnotesList: footnoteText ? [{ marker: '[1]', title: 'Archival Citation', text: footnoteText, url: '' }] : [],
            footnotes: footnoteText,
            activeGalleryIndex: 0,
            galleries: [
                {
                    id: 'gal_' + Date.now() + '_1',
                    title: `${title} Primary Tray`,
                    subtitle: 'Baseline Forensic Evidence',
                    activePhotoIndex: 0,
                    photos: [
                        { url: photoUrl, caption: photoCaption, badge: badge }
                    ]
                }
            ]
        };

        g.startingPointPosts.unshift(newPost);
        g.saveGame();
        this.showToast('🚀 New Before Post published successfully!');
        this.renderStartingPointTab();
        this.jumpToHistoryTarget('history-post-' + newPost.id);
        if (typeof this.masterSaveAll === 'function') {
            this.masterSaveAll().catch(e => console.warn(e));
        }
    }

