    deleteActiveBeforeAfterPair() {
        const g = window.Game;
        if (!Array.isArray(g.beforeAfterComparisons) || g.beforeAfterComparisons.length <= 1) {
            this.showToast('⚠️ Cannot delete the only comparison pair.');
            return;
        }
        if (!confirm('Are you sure you want to remove this comparison pair?')) return;
        const idx = g.activeBeforeAfterIndex || 0;
        g.beforeAfterComparisons.splice(idx, 1);
        g.activeBeforeAfterIndex = Math.max(0, idx - 1);
        g.saveGame();
        this.renderStartingPointTab();
        this.showToast('🗑️ Comparison pair removed.');
        if (typeof this.masterSaveAll === 'function') {
            this.masterSaveAll().catch(e => console.warn(e));
        }
    }

    handleBeforeAfterSlide(e, container) {
        if (!container) return;
        const rect = container.getBoundingClientRect();
        const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
        const pct = (x / rect.width) * 100;
        const clip = container.querySelector('#before-clip-layer');
        const knob = container.querySelector('#slider-handle-knob');
        if (clip) clip.style.width = pct + '%';
        if (knob) knob.style.left = pct + '%';
    }

    handleBeforeAfterTouch(e, container) {
        if (!container || !e.touches || !e.touches[0]) return;
        const touch = e.touches[0];
        const rect = container.getBoundingClientRect();
        const x = Math.max(0, Math.min(touch.clientX - rect.left, rect.width));
        const pct = (x / rect.width) * 100;
        const clip = container.querySelector('#before-clip-layer');
        const knob = container.querySelector('#slider-handle-knob');
        if (clip) clip.style.width = pct + '%';
        if (knob) knob.style.left = pct + '%';
    }

    quickAddJackTurn(turnText, pierText) {
        const g = window.Game;
        if (!Array.isArray(g.levelingLogs)) g.levelingLogs = [];
        const latest = g.levelingLogs[g.levelingLogs.length - 1] || { remainingSag: '-3.50"' };
        const curSag = Math.abs(parseFloat(latest.remainingSag) || 3.50);
        const delta = turnText.includes('1/16') ? 0.0625 : (turnText.includes('1/8') ? 0.125 : 0.05);
        const newSag = Math.max(0, curSag - delta).toFixed(2);
        const newEntry = {
            id: 'll_' + Date.now(),
            date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            pier: pierText || 'Pier 3 Center',
            turn: turnText || '+1/16"',
            remainingSag: `-${newSag}"`,
            moisture: (16.0 + Math.random() * 2).toFixed(1) + '%',
            status: `Calibrated ${turnText} lift completed cleanly`,
            tech: 'Jack S.'
        };
        g.levelingLogs.push(newEntry);
        g.saveGame();
        this.renderStartingPointTab();
        this.showToast(`🔩 Calibrated ${turnText} turn logged on ${pierText}!`);
        if (typeof this.masterSaveAll === 'function') {
            this.masterSaveAll().catch(e => console.warn(e));
        }
    }

    openAddLevelingLogPrompt() {
        const g = window.Game;
        const pier = prompt('Enter Pier / Jack ID (e.g. Pier 3 Center, East Crawlspace):', 'Pier 3 Center');
        if (!pier) return;
        const turn = prompt('Enter Turn Increment (e.g. +1/16", +1/8", Transit Calibration):', '+1/16"');
        if (!turn) return;
        const sag = prompt('Enter Current Remaining Sag (e.g. -3.25"):', '-3.25"');
        if (!sag) return;
        const moisture = prompt('Enter Timber Moisture (e.g. 16.5%):', '16.5%');
        const notes = prompt('Enter Status / Notes:', 'Laser leveling reading verified');
        const tech = prompt('Enter Technician name:', 'Jack & Crew');

        if (!Array.isArray(g.levelingLogs)) g.levelingLogs = [];
        g.levelingLogs.push({
            id: 'll_' + Date.now(),
            date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            pier,
            turn,
            remainingSag: sag,
            moisture: moisture || '16.0%',
            status: notes || 'Leveling logged',
            tech: tech || 'Jack'
        });
        g.saveGame();
        this.renderStartingPointTab();
        this.showToast('📐 Laser transit reading logged!');
        if (typeof this.masterSaveAll === 'function') {
            this.masterSaveAll().catch(e => console.warn(e));
        }
    }

