    saveCatEditor() {
        const g = window.Game;
        const id = document.getElementById('cat-edit-id')?.value.trim() || ('cat_' + Date.now());
        const name = document.getElementById('cat-edit-name')?.value.trim();
        if (!name) {
            alert('Please enter a cat name.');
            return;
        }
        const catData = {
            id,
            name,
            title: document.getElementById('cat-edit-title')?.value.trim() || 'Resident Cat',
            avatar: document.getElementById('cat-edit-avatar')?.value.trim() || '🐱',
            color: document.getElementById('cat-edit-color')?.value || '#f97316',
            currentRoom: document.getElementById('cat-edit-room')?.value || 'LivingRoom',
            hunger: Number(document.getElementById('cat-edit-hunger')?.value || 30),
            affection: Number(document.getElementById('cat-edit-affection')?.value || 70),
            personality: document.getElementById('cat-edit-personality')?.value.trim() || 'Manor companion',
            favoriteMischief: document.getElementById('cat-edit-mischief')?.value.trim() || 'Exploring rooms'
        };

        const existing = g.cats.find(c => c.id === id);
        if (existing) {
            g.saveCat(id, catData);
        } else {
            g.addCat(catData);
        }

        this.closeCatEditorModal();
        this.renderCatsTab();
        this.showToast(`✅ Saved cat profile: "${name}"!`);
    }

    deleteCatPrompt(catId) {
        const g = window.Game;
        const cat = g.cats.find(c => c.id === catId);
        const name = cat ? cat.name : 'this cat';
        if (!confirm(`Are you sure you want to retire / remove ${name} from the manor?`)) return;
        g.deleteCat(catId);
        this.renderCatsTab();
        this.showToast(`🗑️ ${name} was retired.`);
    }

